$dhx='C:\Users\btdba\DocxHeaderExtractor\dhx.cmd'
if(-not(Test-Path $dhx)){throw "dhx.cmd not found: $dhx"}

function Rj([string]$p){Get-Content -Raw $p|ConvertFrom-Json}
function Wj([string]$p,$v){New-Item -ItemType Directory -Force (Split-Path $p)|Out-Null;$j=($v|ConvertTo-Json -Depth 100);$j=$j.Replace('V3_2','V3_3').Replace('v3.2','v3.3').Replace('V3.2','V3.3');[IO.File]::WriteAllText($p,$j+[Environment]::NewLine,[Text.UTF8Encoding]::new($false))}
function Wt([string]$p,[string]$v){New-Item -ItemType Directory -Force (Split-Path $p)|Out-Null;$t=$v.Trim().Replace('V3_2','V3_3').Replace('v3.2','v3.3').Replace('V3.2','V3.3');[IO.File]::WriteAllText($p,$t+[Environment]::NewLine,[Text.UTF8Encoding]::new($false))}
function Sha([string]$p){(Get-FileHash $p -Algorithm SHA256).Hash.ToLowerInvariant()}
function Rel([string]$p){(Resolve-Path $p).Path.Substring($repo.Length+1).Replace('\','/')}
function N([string]$s){(($s -replace '\s+',' ').Trim())}
function IN([string]$s){(N $s).ToLowerInvariant()}
function PN([string]$s){((IN $s)-replace '[^\p{L}\p{Nd}]+','')}

$out=Join-Path $repo 'artifacts/authority-audit/canonical-batch-v3.3'
