'DOC-0185'='todo10_8/generated-docx/01_phap_quy/005_Luat_Dau_thau_22-2023-QH15_EN.docx';'DOC-0200'='todo10_8/generated-docx/01_phap_quy/020_TT_133-2016_Che_do_ke_toan_SME.docx';'DOC-0201'='todo10_8/generated-docx/01_phap_quy/021_TT_78-2021_Hoa_don_dien_tu.docx';'DOC-0219'='todo10_8/heading_corpus_100/02_hop_dong_mua_sam/039_WB_EPC_Turnkey_SingleStage_2025.docx';'DOC-0265'='todo10_8/generated-docx/06_dich_song_ngu/085_Luat_Nha_o_2023_EN.docx';'DOC-0243'='todo10_8/heading_corpus_95_word/04_giao_trinh/063_Advanced_Linear_Algebra.docx';'DOC-0116'='todo10_8/heading_corpus_100/02_hop_dong_mua_sam/031_WB_Framework_Agreement_Consulting_2025.docx';'DOC-0122'='todo10_8/heading_corpus_100/02_hop_dong_mua_sam/037_WB_Plant_TwoStage_2025.docx';'DOC-0216'='todo10_8/heading_corpus_100/02_hop_dong_mua_sam/036_WB_Plant_SingleStage_2025.docx';'DOC-0205'='todo10_8/heading_corpus_100/01_phap_quy/025_ND_47-2020_Chia_se_du_lieu_so.doc';'DOC-0264'='todo10_8/heading_corpus_100/06_dich_song_ngu/084_Luat_Chung_khoan_2019_EN.doc'}
