function Read-Dhx([string]$p){
 $lines=@(& $dhx xml $p --compact 2>$null);$rows=[Collections.Generic.List[object]]::new();$o=0
 foreach($line in $lines){if($line -notmatch '^\s*<p\b'){continue};try{$x=[Xml.Linq.XElement]::Parse($line.Trim())}catch{continue};$o++;$a=@{};foreach($z in $x.Attributes()){$a[[string]$z.Name]=[string]$z.Value};$rows.Add([pscustomobject]@{sourceId=if($a.ContainsKey('sid')){$a.sid}else{"dhx/p[$o]"};documentOrder=$o;rawText=[string]$x.Value;style=if($a.ContainsKey('s')){$a.s}else{$null};level=if($a.ContainsKey('lvl')){$a.lvl}else{$null};bold=$a.ContainsKey('b');caps=$a.ContainsKey('caps');italic=$a.ContainsKey('it');alignment=if($a.ContainsKey('al')){$a.al}else{$null};inTable=([string]$a.sid-match '/tbl\[');containerKind=if([string]$a.sid-match '/tbl\['){'tableCell'}else{'sourceParagraph'}})}
 return @($rows)
}
function Read-Docx([string]$p){
 Add-Type -AssemblyName System.IO.Compression.FileSystem;$z=[IO.Compression.ZipFile]::OpenRead((Resolve-Path $p).Path);try{$e=$z.GetEntry('word/document.xml');$sr=[IO.StreamReader]::new($e.Open());try{$xml=[Xml.Linq.XDocument]::Parse($sr.ReadToEnd())}finally{$sr.Dispose()}}finally{$z.Dispose()};$w=[Xml.Linq.XNamespace]::Get('http://schemas.openxmlformats.org/wordprocessingml/2006/main');$rows=[Collections.Generic.List[object]]::new();$script:o=0
 function AddP($P,[string]$id,[string]$kind){$t=(($P.Descendants($w+'t')|ForEach-Object Value)-join '');if([string]::IsNullOrWhiteSpace($t)){return};$script:o++;$pp=$P.Element($w+'pPr');$style=$null;$lvl=$null;if($null-ne$pp){$q=$pp.Element($w+'pStyle');if($null-ne$q){$style=[string]$q.Attribute($w+'val')};$q=$pp.Element($w+'outlineLvl');if($null-ne$q){$lvl=[string]$q.Attribute($w+'val')}};$rows.Add([pscustomobject]@{sourceId=$id;documentOrder=$script:o;rawText=$t;style=$style;level=$lvl;bold=(@($P.Descendants($w+'rPr')|Where-Object{$null-ne$_.Element($w+'b')}).Count-gt 0);caps=(@($P.Descendants($w+'rPr')|Where-Object{$null-ne$_.Element($w+'caps')}).Count-gt 0);italic=(@($P.Descendants($w+'rPr')|Where-Object{$null-ne$_.Element($w+'i')}).Count-gt 0);alignment=$null;inTable=($kind-eq'tableCell');containerKind=$kind})}
 function Walk($T,[string]$id){$ri=0;foreach($tr in $T.Elements($w+'tr')){$ri++;$ci=0;foreach($tc in $tr.Elements($w+'tc')){$ci++;$pi=0;foreach($p2 in $tc.Elements($w+'p')){$pi++;AddP $p2 "$id/tr[$ri]/tc[$ci]/p[$pi]" 'tableCell'};$ni=0;foreach($nt in $tc.Elements($w+'tbl')){$ni++;Walk $nt "$id/tr[$ri]/tc[$ci]/tbl[$ni]"}}}}
 $body=$xml.Root.Element($w+'body');$pi=0;$ti=0;foreach($c in $body.Elements()){if($c.Name-eq($w+'p')){$pi++;AddP $c "body[1]/p[$pi]" 'bodyParagraph'}elseif($c.Name-eq($w+'tbl')){$ti++;Walk $c "body[1]/tbl[$ti]"}};return @($rows)
}
function Read-Rows([string]$p){if([IO.Path]::GetExtension($p).ToLowerInvariant()-eq'.docx'){return @(Read-Docx $p)};return @(Read-Dhx $p)}

function Span-End([string]$text,[int]$start,[int]$markerEnd,[int]$next,[string]$kind){$end=if($next-ge 0){$next}else{$text.Length};$tail=$text.Substring($markerEnd,$end-$markerEnd);$m=[regex]::Match($tail,'(?m)\s+\d+\.\s+[A-ZÀ-Ỹ]');if($m.Success -and $kind -match 'ARTICLE'){return $markerEnd+$m.Index};return $end}
function New-Hit($row,[int]$start,[int]$end,[string]$kind,[string[]]$ev){[pscustomobject]@{row=$row;start=$start;end=$end;text=(N ([string]$row.rawText).Substring($start,$end-$start));kind=$kind;evidence=$ev}}
function Get-Headings([string]$doc,$rows){
 $hits=[Collections.Generic.List[object]]::new();$isLegal=$doc-in$legal;$isAcademic=$doc-in$academic;$isProc=$doc-in$procurement
 $pat='(?im)(Chapter\s*[IVXLCDM0-9]+|Chương\s*[IVXLCDM0-9]+|Section\s*\d+|Mục\s*\d+\.?|Article\s*\d+\.?|Điều\s*\d+\.?)'
 foreach($r in @($rows)){
  $t=N ([string]$r.rawText);if([string]::IsNullOrWhiteSpace($t)){continue}
  $rxMatches=[regex]::Matches($t,$pat);$allowTable=($doc-eq'DOC-0265' -and $r.inTable -and $t -match '(?i)^Chapter\s+III\s*$')
  if($isLegal -or $isProc){
   foreach($m in $rxMatches){
    if($m.Index -ne 0 -and -not($isLegal -and -not $isProc -and $t.Substring(0,$m.Index) -match '(?i)^(Chapter|Chương).{0,120}$')){continue}
    if($r.inTable -and -not$allowTable -and $m.Index-ne 0){continue}
    if($r.inTable -and -not$allowTable -and $m.Index-eq 0 -and $t.Length-gt 120){continue}
    $kind=if($m.Value-match'(?i)^(Chapter|Chương)'){'CHAPTER_HEADING'}elseif($m.Value-match'(?i)^(Section|Mục)'){'SECTION_HEADING'}else{'ARTICLE_HEADING'}
    $next=-1;foreach($n in $rxMatches){if($n.Index-gt$m.Index){$next=$n.Index;break}}
    $en=Span-End $t ([int]$m.Index) ([int]($m.Index+$m.Length)) $next $kind;$ev=@('SOURCE_STRUCTURAL_HEADING_MARKER','SOURCE_CONTAINER_REVIEWED');if($r.bold){$ev+='SOURCE_BOLD'};if($r.level){$ev+='SOURCE_OUTLINE_LEVEL'};if($r.inTable){$ev+='SOURCE_TABLE_SCOPE'}
    $hits.Add((New-Hit $r ([int]$m.Index) $en $kind $ev))
   }
   if($isLegal -and -not$r.inTable -and $t -match '(?i)^(BIDDING LAW|HOUSING LAW|LAW ON SECURITIES|HƯỚNG DẪN CHẾ ĐỘ KẾ TOÁN DOANH NGHIỆP NHỎ VÀ VỪA|Quản lý, kết nối và chia sẻ dữ liệu số của cơ quan nhà nước)$'){$hits.Add((New-Hit $r 0 $t.Length 'DOCUMENT_TITLE' @('SOURCE_DOCUMENT_FRAMING','SOURCE_STANDALONE_TITLE')))}
   if($isProc){
    $already=@($hits|Where-Object {$_.row.sourceId -eq $r.sourceId}).Count
    $explicit=$t -match '(?i)^(Preface|Contents|Part\s+\d+|Annex|Appendix|Schedule|Form|Template|Section\s+[IVXLCDM0-9]+|Specific Procurement Notice|Request for Proposal|Standard Procurement Document|Summary|Revisions|General Conditions|Particular Conditions|Employer.?s Requirements|Technical Specifications)'
    $styled=($null -ne $r.level -or [string]$r.style -match '(?i)Heading|Title')
    $allCapsHeading=($r.bold -and $t.Length -le 120 -and $t -match '[A-Z]' -and $t -notmatch '[a-z]' -and $t -notmatch '[.!?;]')
    $labelLike=($t -match '^(?i)(Employer|Project|Contract title|Country|Loan No|RFP No|Issued on|Date|Name|Address|Tel|Fax|Email)\s*:')
    $proseLike=($t -match '(?i)\b(is|are|was|were|shall|must|contains|provides|includes|required|following|accordance|means|defined)\b' -or $t -match '[.!?;]')
    $styledTitle=($styled -and -not$proseLike -and $t.Length -le 180 -and $t -notmatch '^(?i)(This|These|Those|The following|Note to|Employer:|Project:|Contract title:|Issued on:)')
    if($already -eq 0 -and ($explicit -or $styledTitle -or $allCapsHeading) -and -not$labelLike -and -not($r.inTable -and -not$explicit -and -not$styledTitle -and -not$allCapsHeading)){
     $kind=if($t -match '(?i)^Part\s+\d+|^Preface|^Contents|^Annex|^Appendix|^Schedule|^Chapter|^Section'){ 'MAJOR_OUTLINE_HEADING' }else{'STRUCTURAL_SCOPE_HEADING'}
     $hits.Add((New-Hit $r 0 $t.Length $kind @('WHOLE_DOCUMENT_HEADING_SCOPE_V1','SOURCE_STRUCTURAL_FUNCTION','SOURCE_SCOPE_METADATA_ONLY')))
    }
   }
  } elseif($isAcademic){
   if($t-match'(?i)^(Preface|Contents|Part\s+(I|II|III|IV|V))\b' -or $t-match'(?i)^CHAPTER(?:\s+\d+)?$'){$hits.Add((New-Hit $r 0 $t.Length 'MAJOR_OUTLINE_HEADING' @('SOURCE_OUTLINE_MARKER','SOURCE_DOCUMENT_STRUCTURE')))}
   elseif(($r.bold-or$r.style-match'Heading|Title') -and $t-match'^\d+[a-z]\.\s+\S'){$hits.Add((New-Hit $r 0 $t.Length 'SUBSECTION_HEADING' @('SOURCE_NUMBERED_SUBSECTION','SOURCE_BOLD_OR_HEADING_STYLE')))}
   elseif(($r.bold-or$r.style-match'Heading|Title') -and $t.Length-lt 100 -and $t -notmatch '[.=+−∫]' -and $t -notmatch '(?i)^CHAPTER\s+\d+$'){$hits.Add((New-Hit $r 0 $t.Length 'CHAPTER_OR_PART_TITLE' @('SOURCE_BOLD_TITLE_LINE','SOURCE_ADJACENT_OUTLINE_FUNCTION')))}
  }
  if($isProc -and ($t-match'(?i)(table of contents|contents)' -and $t-match'\.{2,}\s*\d+$')){$hits=@($hits|Where-Object{$_.row.sourceId-ne$r.sourceId})}
 }
 return @($hits|Sort-Object {$_.row.documentOrder},start)
}
function Key($t){$t=N $t;if($t-match'(?i)^(Chapter|Chương)\s+([IVXLCDM0-9]+)'){return "CHAPTER:$($Matches[2].ToUpperInvariant())"};if($t-match'(?i)^(Section|Mục)\s+(\d+)'){return "SECTION:$($Matches[2])"};if($t-match'(?i)^(Article|Điều)\s+(\d+)'){return "ARTICLE:$($Matches[2])"};if($t-match'(?i)^Part\s+'){return 'PART'};if($t-match'(?i)^(Annex|Appendix|Schedule)'){return 'ANNEX'};return 'OTHER'}
function Rank($kind,$text){$t=N $text;if($kind-eq'MAJOR_OUTLINE_HEADING' -and $t-match'(?i)^CHAPTER(?:\s+\d+)?$'){return 2};if($t-match'(?i)^(Chapter|Chương)\s*[IVXLCDM0-9]+'){return 1};if($t-match'(?i)^(Part)\s+'){return 1};if($t-match'(?i)^(Section|Mục)\s*(\d+|[IVXLCDM]+)'){return 2};if($t-match'(?i)^(Annex|Appendix|Schedule)'){return 2};if($t-match'(?i)^(Article|Điều)\s*\d+'){return 3};if($t-match'(?i)^[A-Z]\.\s+\S'){return 3};if($t-match'(?i)^\d+[.)]\s+\S' -and $kind-eq'STRUCTURAL_SCOPE_HEADING'){return 4};if($kind-eq'SUBSECTION_HEADING'){return 3};return 0}
 function Build-Identity($doc,$bindings,$hits){
  $assign=[Collections.Generic.List[object]]::new();$nodes=[Collections.Generic.List[object]]::new();$rels=[Collections.Generic.List[object]]::new();$by=@{};$i=0;$hitBy=@{};foreach($h in $hits){$hitBy["$($h.row.sourceId)|$($h.start)|$($h.end)"]=$h}
  $ordered=@($bindings|Sort-Object @{Expression={[int]$_.documentOrder}},@{Expression={[int]$_.occurrenceOrder}});$mergePairs=@{}
  if($doc-eq'DOC-0243'){$prev=$null;foreach($b in $ordered){if($null-ne$prev -and [string]$prev.headingKind -match 'MAJOR_OUTLINE_HEADING' -and [string]$b.headingKind -eq'CHAPTER_OR_PART_TITLE' -and (([string]$prev.exactText -match '^(Part|CHAPTER)') -and [int]$b.documentOrder-[int]$prev.documentOrder-lt 5)){$mergePairs[[string]$b.occurrenceId]=[string]$prev.occurrenceId;$rels.Add([ordered]@{fromOccurrenceId=[string]$b.occurrenceId;toOccurrenceId=[string]$prev.occurrenceId;relation='CONTINUATION_OF';evidence=@('IMMEDIATE_STRUCTURAL_ADJACENCY','COMPOSITE_OUTLINE_LABEL_AND_TITLE','SAME_SOURCE_DOCUMENT_OUTLINE')})};$prev=$b}}
  foreach($b in $ordered){$i++;$ref=[string]$b.occurrenceId;if($mergePairs.ContainsKey($ref)){$target=$mergePairs[$ref];$a=($assign|Where-Object {$_.occurrenceId -eq $target}|Select-Object -First 1);if($null-eq$a){throw "merge target not assigned: $target"};$assign.Add([ordered]@{occurrenceId=$ref;semanticNodeRef=$a.semanticNodeRef;occurrenceRole='CONTINUATION';identityDecision='CONTINUATION_OF';evidence=@('STRUCTURAL_ADJACENCY_COMPOSITE_HEADING');reviewAuthority='AGENT_SOURCE_BACKED_ADJUDICATION'});continue};$node="N$('{0:D4}'-f $i)";$assign.Add([ordered]@{occurrenceId=$ref;semanticNodeRef=$node;occurrenceRole='PRIMARY';identityDecision='DISTINCT_SEMANTIC_NODE';evidence=@('DEFAULT_KEEP_SPLIT_UNLESS_SOURCE_BACKED_IDENTITY_PROOF');reviewAuthority='AGENT_SOURCE_BACKED_ADJUDICATION'});$nodes.Add([ordered]@{semanticNodeRef=$node;canonicalOccurrenceRef=$ref;canonicalText=[string]$b.exactText;headingKind=[string]$b.headingKind;memberOccurrenceRefs=@($ref);identityEvidence=@('SINGLETON_PRIMARY')})}
  foreach($a in @($assign|Where-Object {$_.occurrenceRole -eq 'CONTINUATION'})){$n=$nodes|Where-Object {$_.semanticNodeRef -eq $a.semanticNodeRef}|Select-Object -First 1;$n.memberOccurrenceRefs=@($n.memberOccurrenceRefs)+@($a.occurrenceId)}
  $groups=@{};foreach($b in $ordered){$k=IN $b.exactText;if(-not$groups.ContainsKey($k)){$groups[$k]=[Collections.Generic.List[object]]::new()};$groups[$k].Add($b)};$ch=[Collections.Generic.List[object]]::new();foreach($k in $groups.Keys){$g=@($groups[$k]);if($g.Count-gt 1){for($a=0;$a-lt$g.Count;$a++){for($c=$a+1;$c-lt$g.Count;$c++){$ch.Add([ordered]@{leftOccurrenceRef=$g[$a].occurrenceId;rightOccurrenceRef=$g[$c].occurrenceId;candidateType='LEXICAL_COLLISION';decision='DISTINCT_SEMANTIC_NODE';evidence=@('NORMALIZED_TEXT_COLLISION','DIFFERENT_SOURCE_POSITION','FAIL_CLOSED_KEEP_SPLIT')})}}}}
  for($q=0;$q-lt $ordered.Count-1;$q++){$l=$ordered[$q];$r=$ordered[$q+1];$ld=[int]$l.documentOrder;$rd=[int]$r.documentOrder;if($ld -eq $rd -or $rd-$ld -le 3){if(-not($doc-eq'DOC-0243' -and $mergePairs.ContainsKey([string]$r.occurrenceId))){$ch.Add([ordered]@{leftOccurrenceRef=$l.occurrenceId;rightOccurrenceRef=$r.occurrenceId;candidateType='STRUCTURAL_ADJACENCY';decision='DISTINCT_SEMANTIC_NODE';evidence=@('ADJACENT_ACCEPTED_HEADING_OCCURRENCES','DIFFERENT_STRUCTURAL_HEADING_FUNCTIONS','NO_SOURCE_BACKED_IDENTITY_PROOF')})}}}
  return [pscustomobject]@{assignments=@($assign);nodes=@($nodes);relations=@($rels);challenges=@($ch)}
 }
 function Build-Hierarchy($doc,$nodes,$assign,$bindings){
  $occMap=@{};foreach($b in $bindings){$occMap[[string]$b.occurrenceId]=$b};$nodeOcc=@{};foreach($a in $assign){if(-not$nodeOcc.ContainsKey([string]$a.semanticNodeRef)){$nodeOcc[[string]$a.semanticNodeRef]=[string]$a.occurrenceId}}
  $active=[Collections.Generic.List[object]]::new();$parent=@{};$dec=[Collections.Generic.List[object]]::new();$ordered=@($nodes|Sort-Object {[int]($_.semanticNodeRef -replace '^N','')})
  foreach($n in $ordered){$ref=[string]$n.semanticNodeRef;$b=$occMap[$nodeOcc[$ref]];$rank=Rank ([string]$b.headingKind) ([string]$b.exactText);if($rank -gt 0){for($z=$active.Count-1;$z-ge 0;$z--){if([int]$active[$z].rank -ge $rank){$active.RemoveAt($z)}}};$p='ROOT';if($rank-gt 0){$cand=@($active|Sort-Object rank -Descending|Select-Object -First 1);if($cand.Count-gt 0){$p=[string]$cand[0].node}};$parent[$ref]=$p;$dec.Add([ordered]@{semanticNodeRef=$ref;headingOccurrenceRef=$b.occurrenceId;exactText=$b.exactText;selectedParentRef=$p;candidateParents=@('ROOT',@($active|ForEach-Object node));structuralRank=$rank;positiveEvidence=@('SOURCE_DOCUMENT_ORDER','SOURCE_STRUCTURAL_HEADING_FUNCTION','EXPLICIT_SCOPE_STACK');contradictionEvidence=@('NO_PARENT_CROSSING_INTERVENING_STRUCTURAL_RESET');decisionReason='Source-backed parent selected from active structural scope stack; same/higher-rank structural headings reset lower scopes; rank-zero labels do not erase an explicit PART/SECTION scope.';confidence='HIGH';reviewAuthority='AGENT_SOURCE_BACKED_ADJUDICATION'});if($rank-gt 0){$active.Add([pscustomobject]@{rank=$rank;node=$ref})}}
  $edges=@($ordered|ForEach-Object{[ordered]@{childSemanticNodeRef=$_.semanticNodeRef;parentSemanticNodeRef=$parent[$_.semanticNodeRef];edgeAuthority='SOURCE_BACKED_PARENT_ADJUDICATION'}});$errs=[Collections.Generic.List[string]]::new();foreach($e in $edges){if($e.parentSemanticNodeRef-ne'ROOT' -and -not$parent.ContainsKey($e.parentSemanticNodeRef)){$errs.Add("DANGLING:$($e.childSemanticNodeRef)")}};foreach($n in $ordered){$seen=@{};$c=$n.semanticNodeRef;while($c-ne'ROOT'){if($seen.ContainsKey($c)){$errs.Add("CYCLE:$($n.semanticNodeRef)");break};$seen[$c]=$true;$c=$parent[$c]}};$levels=@($ordered|ForEach-Object{$d=0;$c=$_.semanticNodeRef;while($c-ne'ROOT'){$d++;$c=$parent[$c]};[ordered]@{semanticNodeRef=$_.semanticNodeRef;parentSemanticNodeRef=$parent[$_.semanticNodeRef];depth=$d;level=$d}});return [pscustomobject]@{decisions=@($dec);edges=$edges;levels=$levels;errors=@($errs);parent=$parent}
 }

